#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/printk.h>
#include <stdlib.h> /* For k_malloc/k_free */
#include <string.h> /* For memset */

#define TEST_BUFFER_SIZE 128

/**
 * @brief Test function to simulate memory allocation and deallocation.
 *
 * This test addresses a potential double-free scenario by ensuring
 * that a pointer is set to NULL after being freed. This prevents
 * subsequent accidental calls to k_free() on the same memory block,
 * which would lead to heap corruption.
 */
void test_read(void)
{
    char *buf = k_malloc(TEST_BUFFER_SIZE);
    zassert_not_null(buf, "Failed to allocate buffer", NULL);

    printk("Allocated buffer at %p\n", buf);

    /* Simulate some operations with the buffer */
    memset(buf, 0xAA, TEST_BUFFER_SIZE);

    /* First free operation */
    printk("First free of buffer at %p\n", buf);
    k_free(buf);
    /* FIX: After freeing, set the pointer to NULL to prevent accidental double-free.
     * k_free(NULL) is a safe no-op in Zephyr's heap implementation.
     */
    buf = NULL;

    /* Simulate a scenario where k_free might be called again on the same pointer
     * (e.g., due to complex control flow, error handling, or a bug).
     * If 'buf' was not set to NULL, this would cause a double-free and heap corruption.
     */
    printk("Attempting second free of buffer at %p (should be NULL or safe)\n", buf);
    k_free(buf); /* This will now be k_free(NULL) and safe. */

    printk("test_read completed successfully, double-free prevented.\n");
}

ZTEST_SUITE(heap_api_tests, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT(heap_api_tests, test_read);
